using System.Windows;using System.Windows.Controls;using SaarOSS.Rechnungsprogramm.Models;using SaarOSS.Rechnungsprogramm.Services;
namespace SaarOSS.Rechnungsprogramm.Views;
public partial class NumberingView:UserControl
{
 private readonly CustomerService _customers=new();private CustomerStore _customerStore=new();private readonly InvoiceService _invoices=new();private InvoiceStore _invoiceStore=new();
 public NumberingView(){InitializeComponent();LoadAll();}
 private void LoadAll(){try{_customerStore=_customers.Load();_invoiceStore=_invoices.LoadInvoices();CustomerPrefixBox.Text=_customerStore.NumberPrefix;CustomerDigitsBox.Text=_customerStore.NumberDigits.ToString();CustomerNextBox.Text=_customerStore.NextSequenceNumber.ToString();InvoicePrefixBox.Text=_invoiceStore.InvoicePrefix;InvoiceDigitsBox.Text=_invoiceStore.InvoiceDigits.ToString();InvoiceNextBox.Text=_invoiceStore.NextInvoiceNumber.ToString();IncludeYearBox.IsChecked=_invoiceStore.IncludeYear;UpdatePreview();}catch(Exception ex){MessageBox.Show(ex.Message,"Nummernkreise",MessageBoxButton.OK,MessageBoxImage.Error);}}
 private void Changed(object sender,TextChangedEventArgs e){if(IsLoaded)UpdatePreview();}private void ChangedClick(object sender,RoutedEventArgs e)=>UpdatePreview();
 private void UpdatePreview(){if(int.TryParse(CustomerDigitsBox?.Text,out var cd)&&int.TryParse(CustomerNextBox?.Text,out var cn))CustomerPreviewText.Text=$"Vorschau: {CustomerPrefixBox.Text.Trim()}{cn.ToString().PadLeft(cd,'0')}";if(int.TryParse(InvoiceDigitsBox?.Text,out var id)&&int.TryParse(InvoiceNextBox?.Text,out var n)){var y=IncludeYearBox.IsChecked==true?DateTime.Today.Year+"-":"";InvoicePreviewText.Text=$"Vorschau: {InvoicePrefixBox.Text.Trim()}{y}{n.ToString().PadLeft(id,'0')}";}}
 private void SaveCustomerNumbering(object sender,RoutedEventArgs e){if(!int.TryParse(CustomerDigitsBox.Text,out var d)||!int.TryParse(CustomerNextBox.Text,out var n)){MessageBox.Show("Bitte gültige Zahlen eingeben.","Nummernkreis",MessageBoxButton.OK,MessageBoxImage.Warning);return;}try{_customers.SaveNumbering(_customerStore,CustomerPrefixBox.Text,d,n);CustomerPreviewText.Text="✓ Kundennummernkreis gespeichert";}catch(Exception ex){MessageBox.Show(ex.Message,"Nummernkreis",MessageBoxButton.OK,MessageBoxImage.Warning);}}
 private void SaveInvoiceNumbering(object sender,RoutedEventArgs e){if(!int.TryParse(InvoiceDigitsBox.Text,out var d)||!int.TryParse(InvoiceNextBox.Text,out var n)){MessageBox.Show("Bitte gültige Zahlen eingeben.","Nummernkreis",MessageBoxButton.OK,MessageBoxImage.Warning);return;}try{_invoices.SaveNumbering(_invoiceStore,InvoicePrefixBox.Text,IncludeYearBox.IsChecked==true,d,n);InvoicePreviewText.Text="✓ Rechnungsnummernkreis gespeichert";}catch(Exception ex){MessageBox.Show(ex.Message,"Nummernkreis",MessageBoxButton.OK,MessageBoxImage.Warning);}}
}
